import manifest from '../../assets/img/manifest.json';

// Generated by scripts/optimize-images.mjs (npm run images)
const files = import.meta.glob('../../assets/img/*.{avif,webp}', { eager: true, query: '?url', import: 'default' });
const url = (name, w, ext) => files[`../../assets/img/${name}-${w}.${ext}`];

// Responsive <picture> with AVIF + WebP, explicit dimensions and lazy loading unless `priority`
export default function Picture({
  name, alt, sizes = '100vw', priority = false, position, className = '', imgClassName = '',
}) {
  const m = manifest[name];
  if (!m) throw new Error(`Unknown image "${name}". Run npm run images.`);
  const srcSet = (ext) => m.widths.map((w) => `${url(name, w, ext)} ${w}w`).join(', ');
  const fallbackWidth = m.widths.find((w) => w >= 1024) ?? m.widths[m.widths.length - 1];

  return (
    <picture className={className}>
      <source type="image/avif" srcSet={srcSet('avif')} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet('webp')} sizes={sizes} />
      <img
        src={url(name, fallbackWidth, 'webp')}
        alt={alt}
        width={m.width}
        height={m.height}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchpriority={priority ? 'high' : undefined}
        style={position ? { objectPosition: position } : undefined}
        className={imgClassName}
      />
    </picture>
  );
}
